// Deletes what else the account owns and its own server keeps of it
// (DeleteAccountService::ASSOCIATIONS_ON_SUSPEND): its notes about other
// accounts, endorsements, aliases, conversation mutes, filters, domain
// blocks, featured tags, list memberships, migrations, lists, report notes,
// scheduled statuses, status pins, followed tags, notification permissions
// and status trends. Notes, endorsements and lists of other accounts about
// it are theirs and are kept. These are short per account, so one statement
// takes them all.
func (q *Queries) PurgeAccountAssociations(ctx context.Context, accountID int64) error {
	_, err := q.db.Exec(ctx, purgeAccountAssociations, accountID)
	return err
}

const purgeAccountProfile = `-- name: PurgeAccountProfile :exec
WITH purged AS (
    UPDATE accounts SET
        silenced_at = NULL,
        suspended_at = COALESCE(accounts.suspended_at, now()),
        suspension_origin = 0,
        locked = false,
        memorial = false,
        discoverable = false,
        indexable = false,
        trendable = false,
        display_name = '',
        note = '',
        fields = '[]'::jsonb,
        moved_to_account_id = NULL,
        reviewed_at = NULL,
        requested_review_at = NULL,
        also_known_as = '{}',
        avatar_file_name = '',
        avatar_content_type = '',
        avatar_file_size = NULL,
        avatar_updated_at = NULL,
        avatar_remote_url = '',
        avatar_storage_schema_version = NULL,
        header_file_name = '',
        header_content_type = '',
        header_file_size = NULL,
        header_updated_at = NULL,
        header_remote_url = '',
        header_storage_schema_version = NULL,
        updated_at = now()
    WHERE accounts.id = $1
    RETURNING accounts.id
)
UPDATE account_stats SET
    statuses_count = 0,
    following_count = 0,
    followers_count = 0,
    updated_at = now()
WHERE account_stats.account_id IN (SELECT purged.id FROM purged)
`

// Empties the profile of an account whose record deletion keeps
// (DeleteAccountService#purge_profile!): the account stays, suspended
// by this server, under its username, URI and keys, with no profile, no
// images and no counts.
func (q *Queries) PurgeAccountProfile(ctx context.Context, id int64) error {
	_, err := q.db.Exec(ctx, purgeAccountProfile, id)
	return err
}
